#!/usr/bin/env python3
"""Twenty hand-authored short lessons for the capstone, in the existing pilot format."""
from pathlib import Path
from bs4 import BeautifulSoup as BS
import html, json, re
ROOT=Path(__file__).resolve().parents[1]
from build_microlearning import HEAD, TAIL, fix_urls

# Lessons are short by design: the optional code panel does not count as core reading.
# Demo IDs point to working scripts already shipped with courses 2 and 5.
COURSE = {
1:[
 dict(t='Una imagen es un tensor; una carpeta es un dataset',lead='Primero aprendemos a representar una foto y una etiqueta. Sin datos bien organizados, no hay modelo fiable.',q='Si una foto mide 224 × 224 píxeles y tiene tres canales, ¿cuántos números recibe la red?',a='224 × 224 × 3 = 150.528 valores; la etiqueta (gato o perro) se guarda aparte.',body='''<p>Una <strong>imagen RGB</strong> es una cuadrícula: alto × ancho × tres intensidades (rojo, verde y azul). Una <strong>etiqueta</strong> indica la respuesta correcta, por ejemplo <code>gato=0</code> y <code>perro=1</code>. Una carpeta puede servir como etiqueta si contiene fotos de una sola clase.</p><p>El proyecto necesita tres conjuntos independientes: <strong>TRAIN</strong> para aprender, <strong>VALIDATION</strong> para elegir ajustes y <strong>TEST</strong> para medir el resultado al final. No uses la misma foto en dos conjuntos: si el modelo la memoriza, la evaluación deja de ser honesta.</p><div class="callout ejemplo"><span class="lbl">Con números</span><p>Con 1.000 imágenes, un reparto posible es 700 para entrenamiento, 150 para validación y 150 para prueba. No es una norma universal: importa conservar clases y evitar duplicados.</p></div>''',demo='curso2/c2m3-canales-rgb',haz='Modifica los valores de color y observa cómo una misma posición guarda tres números.',observa='Cambiar los canales altera la imagen aunque el número de píxeles sea el mismo.',code='from pathlib import Path\ncarpeta = Path("datos/train/gato")\narchivos = list(carpeta.glob("*.jpg"))\nprint("Imágenes de gato:", len(archivos))',notes=['Importa Path, que permite trabajar con rutas de forma cómoda.','Define la carpeta de ejemplo; hay que adaptarla a tu proyecto.','Busca los archivos JPG de esa carpeta.','Muestra cuántas fotos hay, sin afirmar que el número sea suficiente.'],test=('¿Qué debe mantenerse separado de los datos de entrenamiento?','El conjunto de TEST','La carpeta de imágenes','El tamaño de píxel')),
 dict(t='Keras carga por lotes sin llenar la memoria',lead='En un dataset grande, lo importante es cargar y procesar solo el siguiente grupo de imágenes.',q='¿Tiene sentido cargar 80.000 fotos de 224×224 a la RAM de una vez?',a='No siempre: un pipeline por lotes mantiene el consumo controlado y prepara datos mientras se entrena.',body='''<p><strong>Keras</strong> es una API de alto nivel que facilita crear redes neuronales; normalmente usa TensorFlow como motor. La función <code>image_dataset_from_directory</code> recorre carpetas con nombres de clases y produce lotes de imágenes y etiquetas.</p><p>Un <strong>batch</strong> es un grupo, por ejemplo de 32 imágenes. En cada paso el modelo ve un batch. <code>prefetch</code> prepara el siguiente lote mientras la GPU trabaja con el actual: evita muchos tiempos muertos de lectura.</p><div class="callout ejemplo"><span class="lbl">Con números</span><p>1.024 fotos / 32 por lote = 32 batches por época. La red no aprende solo de 32 fotos: acaba recorriendo las 1.024 a lo largo de esa época.</p></div>''',demo='curso2/c2m5-batches',haz='Cambia el tamaño del lote y mira cuántas iteraciones necesita una época.',observa='Un batch más pequeño suele aumentar el número de pasos por época.',code='import tensorflow as tf\nfrom tensorflow import keras\ntrain = keras.utils.image_dataset_from_directory("datos/train", image_size=(224, 224), batch_size=32)\ntrain = train.prefetch(tf.data.AUTOTUNE)',notes=['Carga TensorFlow, el motor que manipula los tensores.','Importa Keras, la interfaz sencilla para definir y entrenar modelos.','Lee las carpetas y crea batches de 32 imágenes redimensionadas a 224×224.','Prepara datos en paralelo usando los recursos disponibles.'],test=('¿Qué significa batch_size=32?','Procesar 32 ejemplos por lote','Que solo tenemos 32 fotos','Que el modelo tiene 32 neuronas')),
 dict(t='PyTorch separa Dataset y DataLoader',lead='Dataset sabe buscar una imagen; DataLoader sabe agruparlas y entregarlas.',q='¿Quién decide qué imagen corresponde al índice 17 y quién organiza los lotes?',a='Dataset obtiene la muestra; DataLoader selecciona índices, mezcla y arma batches.',body='''<p><strong>PyTorch</strong> es un framework de aprendizaje profundo con control explícito sobre el entrenamiento. Su <code>Dataset</code> define cómo obtener una muestra (<code>imagen, etiqueta</code>). <code>DataLoader</code> organiza esas muestras en lotes y puede barajarlas.</p><p><code>torchvision</code> incluye utilidades para imágenes: <code>ImageFolder</code> aprovecha carpetas por clase; <code>transforms.ToTensor()</code> convierte una imagen PIL de 0–255 a un tensor de forma <code>(C, H, W)</code> en escala 0–1.</p><div class="callout ejemplo"><span class="lbl">Con números</span><p>Si hay 100 fotos y usas batch_size=32, obtendrás cuatro batches: 32, 32, 32 y 4 fotos (salvo que descartes el último).</p></div>''',demo='curso5/c5m3-nchw-memoria',haz='Alterna NCHW y NHWC e identifica dónde están los tres canales.',observa='Keras suele usar (N,H,W,C); PyTorch espera (N,C,H,W).',code='from torchvision import datasets, transforms\nfrom torch.utils.data import DataLoader\nprep = transforms.Compose([transforms.Resize((224, 224)), transforms.ToTensor()])\ndatos = datasets.ImageFolder("datos/train", transform=prep)\nloader = DataLoader(datos, batch_size=32, shuffle=True)',notes=['Importa utilidades de imágenes y transformaciones.','Importa el organizador de lotes de PyTorch.','Redimensiona y convierte cada imagen a tensor.','Lee imágenes y etiqueta usando los nombres de carpeta.','Crea lotes de 32 y mezcla el orden en entrenamiento.'],test=('¿Quién entrega los batches en PyTorch?','DataLoader','ReLU','Softmax')),
 dict(t='Data augmentation: más variedad sin nuevas fotos',lead='Girar o recortar ligeramente puede ayudar a generalizar, pero solo si conserva la etiqueta.',q='Si invertimos horizontalmente la foto de un gato, ¿sigue siendo un gato? ¿Y un número 6 invertido?',a='El gato normalmente sí; un dígito puede cambiar de significado. Una transformación no sirve para todos los problemas.',body='''<p><strong>Data augmentation</strong> crea variaciones durante el entrenamiento: rotaciones pequeñas, zoom, recortes o cambios de luz. No es crear etiquetas nuevas de la nada. Queremos que el modelo reconozca el patrón a pesar de cambios irrelevantes.</p><p>Aplica augmentation <strong>solo en TRAIN</strong>. Validación y test deben reflejar datos reales, con un preprocesado fijo. Un aumento agresivo puede borrar el objeto o alterar el significado: en medicina o imágenes técnicas hay que justificar cada transformación.</p><div class="callout ejemplo"><span class="lbl">Con números</span><p>Una foto puede verse distinta en 10 épocas, pero sigue siendo una observación original. No equivale a reunir diez fotografías independientes.</p></div>''',demo='curso2/c2m5-augmentation',haz='Modifica el grado de transformación y observa qué partes siguen reconocibles.',observa='Más variación no siempre implica mejor calidad: una etiqueta podría dejar de ser válida.',code='import keras\nfrom keras import layers\naumentar = keras.Sequential([\n    layers.RandomFlip("horizontal"),\n    layers.RandomRotation(0.05),\n])',notes=['Importa Keras para crear un modelo secuencial.','Importa las capas de procesamiento de Keras.','Crea una cadena de transformaciones.','Activa volteos horizontales aleatorios.','Aplica giros suaves (factor 0.05) en entrenamiento.','Cierra la definición de la cadena.'],test=('¿En qué conjunto aplicas augmentation aleatorio?','Solo en TRAIN','En TEST para mejorar la nota','Solo en VALIDATION')),
 dict(t='La lista de comprobación antes de entrenar',lead='Dos frameworks distintos deben recibir la misma información y las mismas clases.',q='Un modelo dice 95 % de accuracy y otro 80 %, pero el primero ha visto fotos repetidas en TEST. ¿Quién es mejor?',a='No podemos compararlos: la primera evaluación tiene fuga de datos.',body='''<p>Antes del primer entrenamiento comprueba <strong>número de imágenes, clases, balance, forma de los tensores, duplicados y partición</strong>. Si Keras lee «gato=0» y PyTorch lee «perro=0», una comparación posterior puede estar invertida.</p><p>Usa exactamente el <strong>mismo TEST</strong> para comparar modelos y apunta cualquier diferencia de preprocesado. Al usar modelos preentrenados, no improvises la normalización: utiliza la que exige cada conjunto de pesos.</p><div class="callout ejemplo"><span class="lbl">Ejemplo numérico</span><p>Si TEST tiene 200 imágenes (100 por clase) y has duplicado 50 fotos de TRAIN, el porcentaje final puede subir artificialmente. Corregir el reparto es más importante que cambiar la arquitectura.</p></div>''',demo='curso2/c2m2-normalizar',haz='Prueba distintas escalas de entrada.',observa='La forma y la escala de entrada deben coincidir con las expectativas del modelo.',code='print("Clases:", datos.classes)\nprint("Número de imágenes:", len(datos))\nimagen, etiqueta = datos[0]\nprint("Forma de una imagen:", imagen.shape)',notes=['Consulta el orden real de las carpetas/clases de ImageFolder.','Cuenta las imágenes disponibles.','Obtiene una muestra del Dataset de PyTorch.','Revisa el orden (C,H,W) antes de entrenar.'],test=('¿Qué invalidaría una comparación de modelos?','Que alguno haya visto TEST durante entrenamiento','Usar el mismo conjunto TEST','Guardar la semilla aleatoria'))
],
2:[
 dict(t='Una CNN comparte filtros en toda la imagen',lead='Un filtro pequeño detecta el mismo patrón sin aprender una regla distinta para cada píxel.',q='¿Por qué una CNN suele necesitar menos parámetros que una red Dense que recibe todos los píxeles?',a='Porque la convolución reutiliza los mismos pesos del filtro en distintas posiciones.',body='''<p><strong>CNN</strong> significa red neuronal convolucional. Cada filtro examina pequeñas regiones y genera un <strong>mapa de características</strong>. ReLU introduce no linealidad y MaxPooling resume zonas para reducir las dimensiones.</p><p>Un filtro no sabe de antemano «esto es un gato»: aprende pesos asociados con patrones útiles. Varias capas combinan bordes, texturas y formas. El entrenamiento sigue el ciclo que ya conoces: predicción → pérdida → gradientes → optimizador.</p><div class="callout ejemplo"><span class="lbl">Con números</span><p>Una entrada 32×32×3 pasa por Conv2D con 16 filtros de 3×3 y padding «same»: queda 32×32×16. Un MaxPooling de 2×2 la convierte en 16×16×16.</p></div>''',demo='curso2/c2m3-convolucion-paso',haz='Desplaza el filtro por una pequeña imagen y mira el resultado.',observa='El mismo conjunto de pesos se aplica a cada posición, sin cambiar el filtro.',code='from keras import layers\nentrada = layers.Input(shape=(32, 32, 3))\nx = layers.Conv2D(16, 3, padding="same", activation="relu")(entrada)\nx = layers.MaxPooling2D(2)(x)\nprint(x.shape)',notes=['Importa capas listas para construir una CNN con Keras.','Declara fotos RGB de 32×32.','Aplica 16 filtros de 3×3 sin reducir tamaño espacial.','Reduce alto y ancho a la mitad.','Muestra las dimensiones del resultado simbólico.'],test=('¿Qué se comparte en una convolución?','Los pesos del filtro','La etiqueta del dataset','Las respuestas del TEST')),
 dict(t='Construir una CNN con Keras, capa a capa',lead='En Keras declaras el camino de la imagen y configuras cómo se entrenará.',q='Si quieres dos clases exclusivas, ¿cuántas neuronas pondrías al final con softmax?',a='Dos neuronas, una por clase; softmax convierte sus puntuaciones en valores que suman uno.',body='''<p>En una clasificación binaria puedes usar una neurona con sigmoide o dos con softmax. Aquí usaremos <strong>dos logits</strong> (puntuaciones sin normalizar) y <code>SparseCategoricalCrossentropy(from_logits=True)</code>, que espera etiquetas enteras 0 y 1.</p><p><strong>Sequential</strong> es una pila de capas. <code>compile()</code> elige optimizador, pérdida y métricas; <code>fit()</code> entrena con TRAIN. Tu capacidad para explicar la forma de los tensores vale más que memorizar estas líneas.</p><div class="callout ejemplo"><span class="lbl">Con números</span><p>Imagen 32×32×3 → Conv2D(8) → Pool(2) = 16×16×8 → Flatten = 2.048 números → Dense(2) = dos logits.</p></div>''',demo='curso2/c2m3-constructor-cnn',haz='Cambia el número de filtros y observa dimensiones y parámetros.',observa='Flatten no aprende; una Dense final usa los números que extrae la CNN.',code='import keras\nfrom keras import layers\nmodelo = keras.Sequential([layers.Input((32, 32, 3)),\n    layers.Conv2D(8, 3, padding="same", activation="relu"),\n    layers.MaxPooling2D(2), layers.Flatten(), layers.Dense(2)])\nmodelo.compile(optimizer="adam", loss=keras.losses.SparseCategoricalCrossentropy(from_logits=True), metrics=["accuracy"])',notes=['Importa Keras para construir un modelo.','Importa sus tipos de capas.','Crea una red secuencial con entrada de imagen RGB.','Detecta patrones con ocho filtros pequeños.','Reduce, aplana y produce dos puntuaciones de clase.','Configura Adam, la pérdida multiclase para etiquetas enteras y accuracy.'],test=('¿Por qué from_logits=True en este código?','Porque la capa final no tiene softmax','Porque ya están normalizadas las probabilidades','Porque la entrada es RGB')),
 dict(t='La misma CNN con PyTorch',lead='La idea matemática es idéntica, pero PyTorch explicita más detalles de tensores y entrenamiento.',q='¿Qué forma tiene un lote de 16 imágenes RGB de 32×32 en PyTorch?',a='(16, 3, 32, 32): lote, canales, alto y ancho (NCHW).',body='''<p>PyTorch usa capas como <code>nn.Conv2d</code>, <code>nn.ReLU</code>, <code>nn.MaxPool2d</code> y <code>nn.Linear</code>. Aquí <code>nn.Sequential</code> también sirve para apilar operaciones sin crear una clase.</p><p>La diferencia que más errores causa es la forma: <strong>Keras suele usar NHWC</strong> y <strong>PyTorch NCHW</strong>. El otro detalle importante es que <code>nn.CrossEntropyLoss</code> espera logits (sin softmax) y etiquetas enteras de tipo <code>long</code>.</p><div class="callout ejemplo"><span class="lbl">Con números</span><p>(16,3,32,32) → Conv2d(3,8) → (16,8,32,32) → Pool → (16,8,16,16) → Flatten → (16,2048) → Linear(2048,2).</p></div>''',demo='curso5/c5m3-constructor-cnn',haz='Cambia filtros y capas en el constructor.',observa='El tamaño que entra a Linear debe coincidir con el resultado de Flatten.',code='import torch.nn as nn\nmodelo = nn.Sequential(\n    nn.Conv2d(3, 8, kernel_size=3, padding=1),\n    nn.ReLU(), nn.MaxPool2d(2),\n    nn.Flatten(), nn.Linear(8 * 16 * 16, 2)\n)\nperdida = nn.CrossEntropyLoss()',notes=['Importa las capas del paquete nn de PyTorch.','Empieza una cadena de operaciones.','Recibe tres canales y aprende ocho filtros.','Activa y reduce el tamaño espacial a la mitad.','Aplana las salidas y obtiene dos logits.','Cierra la arquitectura.','Define la pérdida para etiquetas enteras y logits.'],test=('¿Qué forma espera Conv2d en PyTorch?','(N, C, H, W)','(N, H, W, C)','(H, W) sin canales')),
 dict(t='Entrenar: fit en Keras y el bucle explícito en PyTorch',lead='Forward, loss, backward y actualización son los mismos pasos bajo dos estilos distintos.',q='¿Qué ocurre si en PyTorch olvidas poner los gradientes a cero en cada batch?',a='Los gradientes se acumulan y dejan de representar solo ese batch.',body='''<p>Keras encapsula el bucle al ejecutar <code>fit()</code>. En PyTorch suele escribirse: obtener un batch, poner a cero los gradientes, hacer forward, calcular loss, llamar a <code>backward()</code> y después a <code>step()</code>.</p><p><strong>Backpropagation</strong> calcula derivadas de la pérdida respecto de los parámetros; el <strong>optimizador</strong> actualiza esos parámetros. No es lo mismo. Validation mide el comportamiento fuera de TRAIN sin actualizar pesos y permite detener el entrenamiento cuando deja de mejorar.</p><div class="callout ejemplo"><span class="lbl">Con números</span><p>Con 640 imágenes y batch_size=32, una época contiene 20 pasos. Si entrenas 5 épocas completas, habrás procesado 100 batches (salvo cambios en el loader).</p></div>''',demo='curso5/c5m1-paso-entrenamiento',haz='Sigue los pasos y observa cuándo cambian los pesos.',observa='Primero se calcula el error y su gradiente; después se actualizan los parámetros.',code='import torch\nopt = torch.optim.Adam(modelo.parameters(), lr=0.001)\nfor x, y in loader:\n    opt.zero_grad()\n    logits = modelo(x)\n    loss = perdida(logits, y)\n    loss.backward()\n    opt.step()',notes=['Carga PyTorch.','Crea Adam para actualizar los pesos del modelo.','Recorre batches de imágenes y etiquetas.','Borra los gradientes de la iteración anterior.','Realiza la predicción o forward pass.','Compara las predicciones con las respuestas reales.','Calcula los gradientes mediante backpropagation.','Actualiza los parámetros utilizando esos gradientes.'],test=('¿Qué función modifica los parámetros al entrenar en PyTorch?','opt.step()','loss.backward()','modelo(x)')),
 dict(t='Evaluación: una sola cifra puede engañarte',lead='Compara ambos modelos en el mismo TEST y examina qué clases les cuesta reconocer.',q='Si el modelo siempre predice «no hay daño» y el 90 % no tiene daños, ¿es bueno porque acierta el 90 %?',a='No necesariamente: detectaría cero casos positivos. Importan también recall, precision y la matriz de confusión.',body='''<p><strong>Accuracy</strong> es el porcentaje total de aciertos. <strong>Precision</strong> pregunta qué parte de las alarmas acertó. <strong>Recall</strong> pregunta cuántos positivos reales detectó. <strong>F1</strong> combina precision y recall.</p><p>En el proyecto prepara una <strong>matriz de confusión</strong>, métricas por clase y ejemplos de errores. No compares un 85 % de Keras en TEST con un 88 % de PyTorch en TRAIN: están midiendo cosas distintas.</p><div class="callout ejemplo"><span class="lbl">Con números</span><p>De 20 imágenes dañadas detectamos 15: recall = 15/20 = 75 %. Si señalamos 25 imágenes como dañadas y 15 lo estaban: precision = 15/25 = 60 %.</p></div>''',demo='curso2/c2m5-matriz-confusion',haz='Cambia aciertos y errores y compara las métricas.',observa='Dos modelos con accuracy parecida pueden tener recall muy distinto.',code='from sklearn.metrics import classification_report\ny_real = [0, 1, 1, 0, 1]\ny_pred = [0, 1, 0, 0, 1]\nprint(classification_report(y_real, y_pred, zero_division=0))',notes=['Importa el informe de métricas de clasificación.','Representa cinco etiquetas reales de ejemplo.','Representa las cinco decisiones del modelo.','Calcula precision, recall, F1 y support por clase.'],test=('¿Qué métrica mide positivos reales que conseguimos detectar?','Recall','Accuracy del entrenamiento','Número de parámetros'))
],
3:[
 dict(t='ViT convierte imágenes en parches y tokens',lead='Un Vision Transformer procesa la imagen como una secuencia de regiones pequeñas.',q='¿Cuántos parches de 16×16 obtienes de una imagen de 224×224?',a='14 parches por lado; 14×14 = 196 parches o tokens visuales (sin contar posibles tokens especiales).',body='''<p>Un <strong>ViT (Vision Transformer)</strong> es un Transformer adaptado a imágenes. Divide la foto en parches, transforma cada parche en un vector (embedding) y utiliza <strong>atención</strong> para relacionar información entre regiones.</p><p>En una CNN, los filtros empiezan mirando alrededor de un píxel. En un ViT, la atención permite relacionar parches distantes. Esto no implica que un ViT sea siempre mejor: depende de los datos, preentrenamiento y recursos.</p><div class="callout ejemplo"><span class="lbl">Con números</span><p>224/16 = 14. Hay 196 parches; cada parche RGB contiene 16×16×3 = 768 valores antes de la proyección a su embedding.</p></div>''',demo='curso2/c2m4-posicional',haz='Observa cómo se incorpora la posición de los elementos.',observa='Sin posición, el modelo perdería información sobre dónde se encuentra cada parte.',code='alto = 224\nparche = 16\npor_lado = alto // parche\ntokens = por_lado ** 2\nprint(tokens)',notes=['Define el alto de imagen del ejemplo.','Elige parches cuadrados de 16 píxeles.','Calcula cuántos caben en cada lado.','Cuenta los parches de toda la imagen.','Muestra 196 tokens visuales.'],test=('¿Cuántos parches 16×16 caben en 224×224?','196','224','16')),
 dict(t='Atención y posición: el ViT relaciona regiones',lead='El mismo parche visual puede significar algo distinto según su posición y sus vecinos.',q='Si ves «ojo» en la parte inferior de una imagen, ¿la posición puede afectar su interpretación?',a='Sí. Las posiciones y las relaciones con otros parches ayudan a comprender la imagen completa.',body='''<p>La <strong>atención</strong> aprende cuánto debe influir cada token en los demás. Sus piezas son <strong>Query</strong> (qué busca), <strong>Key</strong> (qué puede ofrecer cada token) y <strong>Value</strong> (la información que aporta).</p><p>Un ViT añade información de <strong>posición</strong>, porque una secuencia de parches sin posiciones no describe adecuadamente la distribución espacial. La atención multi-cabeza permite aprender relaciones diferentes al mismo tiempo.</p><div class="callout ejemplo"><span class="lbl">Con números</span><p>Para 196 tokens hay 196×196 = 38.416 parejas token–token posibles en una matriz de atención de una cabeza. No significa que todas tengan el mismo peso.</p></div>''',demo='curso2/c2m4-atencion',haz='Varía la atención para observar qué posiciones influyen más en la salida.',observa='El modelo pondera información; no se limita a contar parches.',code='n_tokens = 196\nrelaciones = n_tokens * n_tokens\nprint(f"Relaciones por cabeza: {relaciones:,}")',notes=['Guarda el número de parches del ejemplo.','Calcula el número de pares entre tokens.','Muestra el total en formato legible.'],test=('¿Qué añade el embedding posicional?','Información de dónde está cada parche','Nuevas etiquetas de TEST','Otra imagen de entrenamiento')),
 dict(t='ViT preentrenado con KerasHub',lead='Reutiliza un Vision Transformer entrenado en imágenes grandes y adapta su cabeza a dos clases.',q='¿Por qué congelar primero el backbone cuando tienes pocas imágenes etiquetadas?',a='Evita modificar millones de pesos útiles de golpe; permite entrenar una cabeza pequeña antes de plantear fine-tuning.',body='''<p><strong>KerasHub</strong> es una biblioteca de modelos preentrenados utilizable con Keras. Su clase <code>ViTBackbone</code> proporciona el extractor visual y <code>ViTImageClassifier</code> añade una cabeza de clasificación. <strong>Transfer learning</strong> reutiliza conocimiento previo.</p><p>El preset de ViT viene con un tamaño y preprocesamiento esperados. Revisa su <strong>preprocessor</strong> y la versión instalada antes de ejecutar: si las entradas no siguen el contrato del modelo, los resultados no serán comparables.</p><div class="callout ejemplo"><span class="lbl">Con números</span><p>Si solo cambias una cabeza de 768 entradas a 2 clases, esa capa tiene 768×2 + 2 = 1.538 parámetros. Es muchísimo menos que entrenar los millones de parámetros del ViT completo.</p></div><p><a href="https://keras.io/keras_hub/api/models/vit/vit_image_classifier/">Documentación oficial del modelo ViT en KerasHub</a>.</p>''',demo='curso2/c2m5-escenarios',haz='Compara congelar la base con afinar más capas.',observa='Congelar limita los parámetros que se actualizan: útil cuando el conjunto etiquetado es pequeño.',code='import keras_hub\nbackbone = keras_hub.models.ViTBackbone.from_preset("vit_base_patch16_224_imagenet")\nbackbone.trainable = False\nmodelo = keras_hub.models.ViTImageClassifier(backbone=backbone, num_classes=2, activation=None)',notes=['Importa KerasHub, que proporciona arquitecturas y pesos preentrenados.','Carga el extractor ViT-B/16 entrenado previamente en ImageNet.','Congela el extractor para entrenar primero solo la cabeza.','Crea un clasificador de dos clases que devuelve logits. Comprueba y aplica el preprocesado del preset antes de fit.'],test=('¿Qué significa backbone.trainable=False?','No cambiar los pesos del extractor al entrenar','Borrar las capas del modelo','Desactivar todas las predicciones')),
 dict(t='ViT preentrenado con TorchVision',lead='En PyTorch puedes cambiar la cabeza final y entrenar solo los parámetros nuevos.',q='Si congelas todas las capas, ¿cómo aprende tu tarea de dos clases?',a='Sustituyendo después la cabeza de clasificación por una capa nueva que queda entrenable.',body='''<p><strong>TorchVision</strong> es la biblioteca de visión de PyTorch. Incluye <code>vit_b_16</code> y el objeto de pesos asociado, que también ofrece las transformaciones esperadas para inferencia.</p><p>El orden importa: carga pesos, congela el modelo y <strong>después</strong> sustituye la cabeza. La cabeza recién creada tiene parámetros entrenables y produce dos logits, uno por clase.</p><div class="callout ejemplo"><span class="lbl">Con números</span><p>Si la cabeza original predice 1.000 clases y tu problema solo tiene 2, no sirve conservarla sin cambios. Reemplazarla permite adaptar las decisiones al nuevo objetivo.</p></div><p><a href="https://docs.pytorch.org/vision/main/models/vision_transformer">Documentación oficial de ViT en TorchVision</a>.</p>''',demo='curso5/c5m4-congelar',haz='Marca qué capas cambian durante el entrenamiento.',observa='Los pesos congelados no reciben actualización del optimizador.',code='from torchvision.models import vit_b_16, ViT_B_16_Weights\nfrom torch import nn\npesos = ViT_B_16_Weights.IMAGENET1K_V1\nmodelo = vit_b_16(weights=pesos)\nfor p in modelo.parameters(): p.requires_grad = False\nmodelo.heads.head = nn.Linear(modelo.heads.head.in_features, 2)',notes=['Importa el constructor ViT y la enumeración de pesos oficiales.','Importa la capa Linear de PyTorch.','Selecciona un conjunto concreto de pesos preentrenados.','Construye el modelo y carga esos pesos. Requiere descarga la primera vez.','Congela los parámetros de las capas existentes.','Sustituye la cabeza original por una nueva Linear con dos logits.'],test=('¿Qué capa hay que adaptar a una nueva cantidad de clases?','La cabeza de clasificación','Los píxeles del dataset','La función print')),
 dict(t='CNN y ViT: elegir con pruebas, no por moda',lead='Una arquitectura es una hipótesis: compárala bajo las mismas condiciones.',q='¿Se puede concluir que ViT es mejor porque tiene más parámetros?',a='No. Un modelo más grande puede costar más, sobreajustar y no mejorar las métricas de interés.',body='''<p>Diseña un experimento justo: <strong>mismos datos, mismo TEST, mismas métricas, presupuestos de entrenamiento comparables</strong>. Registra arquitectura, pesos iniciales, augmentation, épocas y tiempo. Es válido que uno gane en precisión y otro en velocidad o tamaño.</p><p>Una <strong>CNN</strong> incorpora una intuición útil sobre vecindad y filtros. Un <strong>ViT</strong> relaciona parches con atención y suele beneficiarse especialmente del preentrenamiento. También es posible combinar extractores, pero añade complejidad que debes justificar.</p><div class="callout ejemplo"><span class="lbl">Ejemplo hipotético</span><p>CNN: recall 89 % y 8 ms por imagen. ViT: recall 90 % y 24 ms. Si la latencia importa mucho, el 1 % extra quizá no compense. No son resultados de un experimento real.</p></div>''',demo='curso2/c2m3-cnn-vs-dense',haz='Compara capacidad y coste de distintas arquitecturas como intuición visual.',observa='Más capas o parámetros no significan automáticamente mejor modelo.',code='resultados = {"cnn": {"recall": 0.89, "ms": 8}, "vit": {"recall": 0.90, "ms": 24}}\nfor nombre, r in resultados.items():\n    print(nombre, r["recall"], r["ms"])',notes=['Guarda resultados hipotéticos de dos modelos para aprender a comparar.','Recorre cada arquitectura y sus medidas.','Muestra recall y latencia; no atribuyas estas cifras a entrenamientos reales.'],test=('¿Qué hace justa la comparación?','Evaluar ambos sobre el mismo TEST','Entrenar uno con los datos de TEST','Elegir el modelo con nombre más moderno'))
],
4:[
 dict(t='Contar el proyecto como una historia reproducible',lead='Una buena presentación no empieza por el código: empieza por el problema y la decisión.',q='¿Qué pregunta necesita responder el público antes de conocer tu arquitectura?',a='Qué problema se intenta resolver, con qué datos y por qué importa.',body='''<p>Una presentación clara sigue esta cadena: <strong>problema → datos → preparación → modelos → evaluación → decisión</strong>. Si clasifica imágenes, especifica clases, origen de datos, número de imágenes y la forma en que separaste TRAIN, VALIDATION y TEST.</p><p>Después explica por qué comparaste una CNN con un ViT y por qué usaste Keras o PyTorch. Evita decir «la IA reconoció todas las imágenes» si solo has probado un conjunto pequeño. Cada conclusión debe estar respaldada por una medida o una limitación declarada.</p><div class="callout ejemplo"><span class="lbl">Ejemplo</span><p>«Queremos detectar grietas y abolladuras. Disponemos de 1.000 imágenes etiquetadas; usamos 700/150/150 y mantenemos TEST fuera del entrenamiento.» Es un ejemplo de estructura, no un resultado del proyecto.</p></div>''',demo='curso1/c1m6-mapa-proyecto',haz='Recorre las etapas del proyecto de principio a fin.',observa='El entrenamiento es solo una parte del flujo y depende de los pasos anteriores.',code='reporte = {"problema": "clasificar imágenes", "clases": ["grieta", "abolladura"]}\nprint("Objetivo:", reporte["problema"])\nprint("Clases:", ", ".join(reporte["clases"]))',notes=['Crea un registro simple con el objetivo y las clases.','Muestra el objetivo para tu presentación.','Muestra las clases contempladas.'],test=('¿Qué parte debe quedar clara al principio?','Problema y datos disponibles','El número de líneas de código','El logo del framework')),
 dict(t='Presentar métricas con una matriz de confusión',lead='No basta con decir «accuracy 70 %»: explica qué errores comete el modelo.',q='Si hay 30 verdaderos positivos, 10 falsos positivos y 20 falsos negativos, ¿cuál es el recall?',a='30/(30+20)=0,60, es decir, detectó el 60 % de los positivos reales.',body='''<p>La <strong>matriz de confusión</strong> contiene verdaderos negativos (TN), falsos positivos (FP), falsos negativos (FN) y verdaderos positivos (TP). Calcula: <strong>precision = TP/(TP+FP)</strong> y <strong>recall = TP/(TP+FN)</strong>.</p><p>Elige la métrica según el problema. Si perder un defecto es muy peligroso, el coste de FN puede ser alto; si una falsa alarma obliga a revisar a mano, también hay que controlar FP. La métrica no decide sola: interpreta los errores.</p><div class="callout ejemplo"><span class="lbl">Con números</span><p>TN=40, FP=10, FN=20 y TP=30. Accuracy=(40+30)/100=70 %; precision=30/40=75 %; recall=30/50=60 %; F1≈66,7 %.</p></div>''',demo='curso2/c2m5-matriz-confusion',haz='Altera las casillas de la matriz y observa precision y recall.',observa='Mejorar una cifra no garantiza mejorar todas las demás.',code='tp, fp, fn, tn = 30, 10, 20, 40\nprecision = tp / (tp + fp)\nrecall = tp / (tp + fn)\nf1 = 2 * precision * recall / (precision + recall)\nprint(precision, recall, round(f1, 3))',notes=['Define los cuatro resultados de un ejemplo hipotético.','Calcula qué fracción de las alarmas fue correcta.','Calcula qué fracción de positivos reales se detectó.','Calcula la media armónica de precision y recall.','Muestra 0.75, 0.60 y 0.667.'],test=('¿Qué representa FN?','Positivo real que el modelo predice como negativo','Acierto en un positivo','Negativo real detectado correctamente')),
 dict(t='Curvas de entrenamiento: detectar sobreajuste',lead='Dos curvas cuentan si la red está aprendiendo patrones o memorizando TRAIN.',q='TRAIN accuracy sube a 98 %, pero VALIDATION queda en 65 %. ¿Es buena noticia?',a='Es una señal posible de overfitting: acierta el entrenamiento, pero generaliza mal.',body='''<p>Muestra <strong>loss y accuracy de TRAIN y VALIDATION por época</strong>. Si la pérdida de TRAIN baja mientras la de VALIDATION sube, el modelo puede estar memorizando. Comprueba datos, augmentation, capacidad, regularización y early stopping.</p><p>No anuncies mejoras a partir de TEST y luego sigas cambiando el modelo: estarías utilizando el examen final para entrenar decisiones. Elige arquitectura con validación y usa TEST al terminar.</p><div class="callout ejemplo"><span class="lbl">Ejemplo hipotético</span><p>Época 2: TRAIN 78 %, VALIDATION 76 %. Época 15: TRAIN 98 %, VALIDATION 65 %. La segunda cifra muestra peor generalización pese a mejor TRAIN.</p></div>''',demo='curso2/c2m2-earlystopping',haz='Mueve el punto de parada y observa cómo cambia el error de validación.',observa='Más épocas no garantizan mejoras en datos nuevos.',code='historia = modelo.fit(train, validation_data=val, epochs=15)\nprint(historia.history.keys())',notes=['Ejemplo Keras: entrena usando un dataset train y uno val ya preparados previamente.','Muestra los nombres de métricas guardadas para poder dibujar curvas.'],test=('¿Qué sugiere TRAIN muy bueno y VALIDATION malo?','Posible overfitting','Que TEST ya está validado','Que no existen errores')),
 dict(t='Justificar Keras o PyTorch según el proyecto',lead='No hay ganador universal: escoge según control, ecosistema y necesidades reales.',q='¿Qué elegirías para prototipar rápido una CNN con el menor código de entrenamiento?',a='Keras puede resultar más directo; PyTorch ofrece un bucle explícito y flexible. Ambos son válidos.',body='''<p><strong>Keras</strong> suele reducir código repetitivo mediante <code>Sequential</code>, <code>compile()</code> y <code>fit()</code>. <strong>PyTorch</strong> hace muy visible el bucle, los gradientes y las operaciones, y facilita experimentar con lógica personalizada.</p><p>La elección también depende de hardware, disponibilidad de pesos, formatos de exportación, experiencia del equipo y facilidad de mantenimiento. En una entrega seria compara <strong>accuracy, recall, tiempo, uso de memoria y esfuerzo de implementación</strong> en el mismo contexto.</p><div class="callout ejemplo"><span class="lbl">Ejemplo</span><p>Si dos modelos alcanzan el mismo recall, quizá elegirías el que consume menos memoria en el móvil; si necesitas modificar la pérdida en cada paso, podría interesarte un bucle más personalizado.</p></div>''',demo='curso5/c5m4-device',haz='Prueba las opciones de dispositivo y visualiza cómo afecta a dónde se calculan los tensores.',observa='CPU/GPU y memoria también forman parte de las decisiones técnicas.',code='criterios = ["recall", "latencia", "memoria", "mantenimiento"]\nfor criterio in criterios:\n    print("Comparar:", criterio)',notes=['Define criterios que deben compararse de forma justa.','Recorre cada criterio relevante.','Muestra qué medir antes de elegir framework.'],test=('¿Cuál es un criterio razonable para elegir framework?','Rendimiento, mantenimiento y requisitos','Su popularidad en un vídeo','Que siempre hay uno universalmente superior')),
 dict(t='Tu entrega final: resultados, límites y próximos pasos',lead='El proyecto está completo cuando otra persona puede entender, reproducir y cuestionar tus resultados.',q='¿Qué falta si presentas 94 % accuracy sin explicar el conjunto TEST ni enseñar ejemplos erróneos?',a='Falta evidencia para interpretar y reproducir el resultado: procedencia del dato, evaluación y errores.',body='''<p>La entrega puede incluir <strong>objetivo, descripción del dataset, división, arquitectura, hiperparámetros, curvas de aprendizaje, métricas, matriz de confusión, análisis de errores y decisión</strong>. Guarda la semilla, versiones de librerías y pasos de preprocesamiento.</p><p>Termina con <strong>limitaciones</strong>: imágenes fuera del dominio, iluminación diferente, desbalanceo, sesgos, pequeño tamaño de TEST o latencia. Propón una siguiente iteración comprobable en lugar de prometer que el modelo «siempre acertará».</p><div class="callout ejemplo"><span class="lbl">En práctica</span><p>Próximo experimento: «¿Aumenta recall en fotos nocturnas si incluimos más casos nocturnos en TRAIN sin tocar TEST?». Esta pregunta produce un plan medible.</p></div>''',demo='curso2/c2m5-curva-lr',haz='Observa cómo los cambios de entrenamiento pueden afectar a la curva de pérdida.',observa='Las mejoras deben medirse con validación y luego confirmarse una sola vez en TEST.',code='import json\nresumen = {"modelo": "CNN", "accuracy_test": None, "limitaciones": []}\nwith open("resumen_resultados.json", "w", encoding="utf-8") as f:\n    json.dump(resumen, f, ensure_ascii=False, indent=2)',notes=['Importa la herramienta de archivos JSON de Python.','Crea una ficha sin inventar resultados: None indica pendiente.','Abre un archivo para escribir resultados.','Guarda la ficha estructurada y legible.'],test=('¿Qué debe acompañar a un buen resultado?','Cómo se evaluó, errores y limitaciones','Solo el porcentaje más alto','La captura del editor'))
]}


MODULE_META={
1:("Tratamiento de datos: carga y aumento con Keras y PyTorch", "Aprende a construir conjuntos de imágenes seguros, dividirlos, preparar lotes y aumentar datos sin contaminar TEST.", ["Representar imágenes RGB y organizar etiquetas por carpetas.", "Cargar batches con Keras y con PyTorch.", "Aumentar TRAIN sin alterar las clases ni contaminar TEST.", "Comprobar shapes, clases, balances y fugas de datos."]),
2:("Desarrollo de modelos CNN en Keras y PyTorch", "Construye y entrena una CNN en ambos frameworks, sigue cada paso de optimización y evalúa errores de verdad.", ["Calcular formas y filtros de una CNN.", "Implementar una CNN con Keras y otra con PyTorch.", "Entender fit, backward y el optimizador.", "Interpretar precision, recall, F1 y matriz de confusión."]),
3:("Vision Transformers y transfer learning", "Entiende los parches, la atención y los ViT; adapta modelos preentrenados en KerasHub y TorchVision.", ["Calcular parches y tokens de una imagen.", "Explicar la atención y el papel de las posiciones.", "Congelar backbones y sustituir cabezas en ViT.", "Comparar CNN y ViT sin fugas y con métricas justas."]),
4:("Presentación del proyecto final", "Convierte tu entrenamiento en una presentación verificable: metodología, métricas, errores y decisiones.", ["Contar el proyecto desde problema hasta decisión.", "Calcular y presentar las métricas relevantes.", "Leer curvas y reconocer sobreajuste.", "Justificar Keras o PyTorch y explicar limitaciones."])
}

def make_quiz(one,index):
 q,cor,w1,w2=one['test']
 opts=[cor,w1,w2]
 shift=index%3
 opts=opts[shift:]+opts[:shift]
 correct=(0-shift)%3
 data={'titulo':'Mini test · Comprueba la idea', 'preguntas':[
  {'q':q,'opciones':opts,'correcta':correct,'porque':one['a']},
  {'q':'¿Qué conviene hacer después de comprender el ejemplo?', 'opciones':['Probar otro caso y explicar qué cambia','Memorizar números sin contexto','Dar por bueno el resultado sin validar'],'correcta':0,'porque':'Cambiar una entrada y observar la respuesta refuerza la comprensión.'}
 ]}
 return '<section class="quiz mini"><script type="application/json" class="quiz-data">'+json.dumps(data,ensure_ascii=False)+'</script></section>'


def snippet(one):
 lines=one['code'].split('\n')
 nonempty=[x for x in lines if x.strip()]
 assert len(nonempty)==len(one['notes']),(one['t'],len(nonempty),len(one['notes']))
 n=0; rows=[]
 for i,line in enumerate(lines,1):
  if not line.strip():continue
  explanation=one['notes'][n];n+=1
  rows.append(f'<tr data-lines="{i}"><td><code>{html.escape(line.strip()[:110])}</code></td><td>{html.escape(explanation)}</td></tr>')
 return '<details class="profundizar" id="codigo"><summary><span>Código explicado línea a línea<small>Abre el ejemplo para entender qué hace cada instrucción y por qué.</small></span></summary><div class="prof-body"><section><h2 class="sin-num">Código de la lección</h2><article class="snippet" data-lang="python"><header><h3>'+html.escape(one['t'])+'</h3><p class="para-que"><strong>Para qué sirve</strong> '+html.escape(one['lead'])+'</p></header><pre class="code"><code>'+html.escape(one['code'])+'</code></pre><details class="linea-a-linea" open><summary>Línea por línea</summary><table class="lineas"><tbody>'+''.join(rows)+'</tbody></table></details><div class="salida"><strong>Qué comprobar</strong><p>Ejemplo didáctico: adapta las rutas, datasets o variables que procedan y verifica la salida en tu propio entorno. No se afirma que se haya entrenado un modelo real.</p></div></article></section></div></details>'


def main():
 for m,lessons in COURSE.items():
  folder=ROOT/'curso-6'/f'modulo-{m}';folder.mkdir(exist_ok=True)
  info=[]
  for i,l in enumerate(lessons,1):
   dest=f'curso-6/modulo-{m}/leccion-{i}.html'
   pred='<details class="predice"><summary>'+html.escape(l['q'])+'<span class="hint"></span></summary><div><p>'+html.escape(l['a'])+'</p></div></details>'
   demo=f'<figure class="demo" data-demo="{l["demo"]}" data-titulo="Explora: {html.escape(l["t"],quote=True)}"><div class="haz">{html.escape(l["haz"])}</div><div class="observa">{html.escape(l["observa"])}</div></figure>'
   explain=f'<section><h2 id="concepto">La idea y el ejemplo</h2>{l["body"]}</section>'
   recap=f'<div class="resumen"><h2 class="sin-num sin-toc">En tres ideas</h2><ul><li>{html.escape(l["lead"])}</li><li>{html.escape(l["a"])}</li><li>Abre el código y explica cada línea antes de pasar a la siguiente lección.</li></ul></div>'
   content=(HEAD.format(title=html.escape(f'Lección {i} · {l["t"]} · Curso 6 · Cuaderno de IA',quote=True),description=html.escape(l['lead'],quote=True),c=6,m=m,l=i)
     +f'<header class="hero leccion"><div class="hero-grid"><div><p class="eyebrow">Curso 6 · Módulo {m} · Lección {i} de {len(lessons)}</p><h1>{html.escape(l["t"])}</h1><p class="lead">{html.escape(l["lead"])}</p><p class="meta-line"><span class="read-time" data-render="read-time"></span><a href="../modulo-{m}.html">Índice del módulo</a></p></div><div class="hero-tile" aria-hidden="true"></div></div></header>'
     +pred+explain+demo+recap+make_quiz(l,i)+snippet(l)+TAIL)
   (folder/f'leccion-{i}.html').write_text(content,encoding='utf-8')
   info.append({'n':i,'slug':f'leccion-{i}','title':l['t'],'blurb':l['lead'],'min':3})
  # Replace module stub automatically; refresh its index and update curriculum.
  module=ROOT/'curso-6'/f'modulo-{m}.html'
  original=module.read_text(encoding='utf-8')
  original=original.replace('Pendiente de contenido','Cada lección tiene una lectura principal de menos de cinco minutos; ejemplos, demos y código paso a paso.').replace('Las lecciones de este módulo se añadirán próximamente.','Cada lección tiene una lectura principal de menos de cinco minutos y un ejemplo práctico.')
  s=BS(original,'html.parser');hero=s.select_one('.hero .eyebrow')
  if hero:hero.string=f'Curso 6 · Módulo {m} · {len(lessons)} lecciones'
  name, introduction, goals = MODULE_META[m]
  if s.select_one('.hero h1'):s.select_one('.hero h1').string=name
  if s.select_one('.hero .lead'):s.select_one('.hero .lead').string=introduction
  if s.select_one('meta[name="description"]'):s.select_one('meta[name="description"]')['content']=introduction
  if s.title:s.title.string=f'Módulo {m} · {name} · Curso 6 · Cuaderno de IA'
  current_goals=s.select_one('.goals ul')
  if current_goals:
   current_goals.clear()
   for goal in goals:
    row=s.new_tag('li');row.string=goal;current_goals.append(row)
  if s.select_one('[data-render="lesson-list"]') is None:
   pg=s.select_one('.page');pg.append(BS('<h2 id="lecciones" class="sin-num">Lecciones</h2><p>Estudia a tu ritmo. Demos, mini test y código explicado.</p><div data-render="lesson-list"></div>','html.parser'))
  module.write_text(str(s),encoding='utf-8')
  print(f'Curso 6 Módulo {m}: {len(info)} lecciones',flush=True)
  yield m,info

if __name__=='__main__':
 from build_microlearning import insert_curriculum
 insert_curriculum({(6,m):lessons for m,lessons in main()})
